import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    n,k,S=map(int,data.split())
    def f(x,left,s):
        if left==0:return int(s==0)
        if x>n or n-x+1<left or s<0:return 0
        return f(x+1,left-1,s-x)+f(x+1,left,s)
    return f(1,k,S)

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
